def window_indices(length, t, history, horizon):
    if min(length, history, horizon) <= 0 or not 0 <= t < length:
        raise ValueError('invalid window configuration')
    obs = [i if 0 <= i < length else None for i in range(t-history+1, t+1)]
    act = [i if 0 <= i < length else None for i in range(t, t+horizon)]
    return obs, act

import math

def diagonal_gaussian_kl(mu, logvar):
    if not mu or len(mu) != len(logvar):
        raise ValueError('expected equal, nonempty vectors')
    if not all(math.isfinite(x) for x in list(mu)+list(logvar)):
        raise ValueError('nonfinite distribution parameter')
    return 0.5 * sum(m*m + math.exp(v) - 1.0 - v for m,v in zip(mu,logvar))

